require __DIR__ . '/../app/bootstrap.php'; $id=(int)($_GET['id']??0); $q=db()->prepare('SELECT i.*,u.name AS poster_name FROM items i JOIN users u ON u.id=i.user_id WHERE i.id=?'); $q->execute([$id]); $item=$q->fetch(); if(!$item){http_response_code(404);exit('Listing not found.');} $owner=signed_in() && (int)$item['user_id']===(int)current_user()['id']; $errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='claim') { require_login(); verify_csrf(); $message=trim((string)($_POST['message']??'')); if($owner) $errors[]='You cannot claim your own listing.'; if($item['status']!=='Open') $errors[]='This listing is no longer open.'; if(mb_strlen($message)<10 || mb_strlen($message)>700) $errors[]='Add a message between 10 and 700 characters so the poster can verify your claim.'; if(!$errors){$q=db()->prepare('INSERT INTO claims (item_id,claimant_id,message) VALUES (?,?,?)'); try{$q->execute([$id,current_user()['id'],$message]);flash('Your claim has been sent to the listing owner.');redirect('item.php?id='.$id);}catch(PDOException $ex){if((string)$ex->getCode()==='23000')$errors[]='You already have an active claim for this listing.';else throw $ex;}} }
if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='claim-status') { require_login(); verify_csrf(); if(!$owner){http_response_code(403);exit('Only the listing owner can review claims.');} $claimId=(int)($_POST['claim_id']??0); $status=(string)($_POST['status']??''); if(!in_array($status,['Accepted','Declined'],true)) {http_response_code(400);exit('Invalid claim status.');} $pdo=db(); $pdo->beginTransaction(); try { $q=$pdo->prepare('UPDATE claims SET status=? WHERE id=? AND item_id=? AND status="Pending"'); $q->execute([$status,$claimId,$id]); if($q->rowCount() && $status==='Accepted') { $pdo->prepare("UPDATE items SET status='Claimed' WHERE id=? AND status='Open'")->execute([$id]); $pdo->prepare("UPDATE claims SET status='Declined' WHERE item_id=? AND status='Pending'")->execute([$id]); } $pdo->commit(); } catch(Throwable $ex) { $pdo->rollBack(); throw $ex; } flash('Claim review saved.'); redirect('item.php?id='.$id.'#claims'); }
$claims=[]; if($owner){$q=db()->prepare('SELECT c.*,u.name AS claimant_name FROM claims c JOIN users u ON u.id=c.claimant_id WHERE c.item_id=? ORDER BY c.created_at DESC');$q->execute([$id]);$claims=$q->fetchAll();}
page_start($item['title'],'browse'); ?><a class="back-link" href="index.php">← Back to listings</a><section class="detail-layout"><article class="detail-card"><div class="item-card-top"><span class="badge <?= $item['kind']==='Lost'?'badge-lost':'badge-found' ?>"><?= e($item['kind']) ?></span><span class="category"><?= e($item['category']) ?></span><span class="status status-<?= e(strtolower($item['status'])) ?>"><?= e($item['status']) ?></span></div><h1><?= e($item['title']) ?></h1><div class="detail-meta"><span>⌖ <?= e($item['location']) ?></span><span>Reported <?= e(format_date($item['event_date'])) ?></span><span>Posted by <?= e($item['poster_name']) ?></span></div><hr><h3>Details</h3><p class="preserve-lines"><?= e($item['description']) ?></p><div class="safety-note"><strong>Stay safe</strong><br>Arrange to meet in a public campus location. Verify ownership using a detail the listing does not reveal.</div><?php if(!$owner && $item['status']==='Open'): ?><div class="claim-box"><h3>Think this could be yours?</h3><p class="muted">Share a detail that helps the poster verify your claim. Your name is visible to them.</p><?php if(!signed_in()): ?><a href="login.php" class="button">Sign in to send a claim</a><?php else: ?><?php if($errors): ?><div class="error-list"><?php foreach($errors as $error): ?><p><?= e($error) ?></p><?php endforeach; ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="claim"><label>Claim message<textarea name="message" rows="3" required minlength="10" maxlength="700" placeholder="Describe a detail that proves it belongs to you..."></textarea></label><button class="button">Send claim</button></form><?php endif; ?></div><?php endif; ?></article><aside class="poster-card"><span class="eyebrow">LISTING OWNER</span><div class="avatar"><?= e(mb_strtoupper(mb_substr($item['poster_name'],0,1))) ?></div><h3><?= e($item['poster_name']) ?></h3><p class="muted">Member since <?= e(date('Y',strtotime($item['created_at']))) ?></p><?php if($owner): ?><a class="button button-outline button-full" href="item-form.php?id=<?= (int)$id ?>">Edit listing</a><?php else: ?><p class="small-note">Contact is kept private. Use the claim form and the owner can respond in the app.</p><?php endif; ?></aside></section>
<?php if($owner): ?><section id="claims" class="claims-section"><div class="section-head"><div><span class="eyebrow">OWNER TOOLS</span><h2>Claim requests</h2></div></div><?php if(!$claims): ?><div class="empty-state compact"><p>No claims have been sent yet.</p></div><?php else: ?><div class="my-listings"><?php foreach($claims as $claim): ?><article class="listing-row claim-row"><div class="listing-main"><h3><?= e($claim['claimant_name']) ?></h3><p class="preserve-lines"><?= e($claim['message']) ?></p><small><?= e(format_date($claim['created_at'])) ?></small></div><span class="status status-<?= e(strtolower($claim['status'])) ?>"><?= e($claim['status']) ?></span><?php if($claim['status']==='Pending'): ?><form method="post" class="claim-actions"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="claim-status"><input type="hidden" name="claim_id" value="<?= (int)$claim['id'] ?>"><button class="button button-small" name="status" value="Accepted" data-confirm="Accept this claim and close the listing?">Accept</button><button class="button button-small button-outline" name="status" value="Declined">Decline</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section><?php endif; ?><?php page_end(); ?>
